SELECT id, session_id, event_type, duration_sec, MIN(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_duration_sec, COUNT(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_duration_sec, MAX(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_duration_sec, AVG(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_duration_sec FROM web_events WHERE session_id IN (11, 31, 38);
